/// Renders the spec model as Dart source: models, enums, namespaces, error codes, and one
/// spec-example call per operation.
library;

import 'dart:convert';

import 'spec.dart';

const header =
    '// Generated by tool/generate.dart from the OpenAPI spec. Do not edit.\n';

/// A `///` comment for [text]. Brackets outside code spans are escaped so a description never
/// reads as a doc reference.
String doc(String? text, [String indent = '']) {
  final body = (text ?? '').trim();
  if (body.isEmpty) return '';
  final lines = body.split('\n').map((line) {
    final parts = line.trimRight().split('`');
    for (var i = 0; i < parts.length; i += 2) {
      parts[i] = parts[i].replaceAllMapped(
        RegExp(r'[\[\]]'),
        (m) => '\\${m[0]}',
      );
    }
    return parts.join('`');
  });
  return lines
      .map((l) => l.isEmpty ? '$indent///\n' : '$indent/// $l\n')
      .join();
}

String dartString(String value) =>
    "'${value.replaceAll(r'\', r'\\').replaceAll("'", r"\'").replaceAll(r'$', r'\$').replaceAll('\n', r'\n').replaceAll('\r', r'\r')}'";

String typeCode(TypeRef t) {
  final base = switch (t) {
    ScalarType(scalar: Scalar.string) => 'String',
    ScalarType(scalar: Scalar.integer) => 'int',
    ScalarType(scalar: Scalar.number) => 'num',
    ScalarType(scalar: Scalar.boolean) => 'bool',
    ScalarType(scalar: Scalar.any) => 'Object?',
    ScalarType(scalar: Scalar.object) => 'Map<String, Object?>',
    NumOrStringType() => 'NumOrString',
    EnumType(:final occurrence) => occurrence.name,
    ModelType(:final name) => name,
    ListType(:final item) => 'List<${typeCode(item)}>',
    MapType(:final value) => 'Map<String, ${typeCode(value)}>',
  };
  return t.nullable && !base.endsWith('?') ? '$base?' : base;
}

bool _isAny(TypeRef t) => t is ScalarType && t.scalar == Scalar.any;

/// The decoder of a non-null [t]; a nullable element is wrapped in `nullable`.
String decoder(TypeRef t) => switch (t) {
  ScalarType(scalar: Scalar.string) => 'asString',
  ScalarType(scalar: Scalar.integer) => 'asInt',
  ScalarType(scalar: Scalar.number) => 'asNum',
  ScalarType(scalar: Scalar.boolean) => 'asBool',
  ScalarType(scalar: Scalar.any) => 'asAny',
  ScalarType(scalar: Scalar.object) => 'asObject',
  NumOrStringType() => 'asNumOrString',
  EnumType() => fail('a response enum is read as a String'),
  ModelType(:final name) => 'model($name.fromJson)',
  ListType(:final item) => 'listOf(${_element(item)})',
  MapType(:final value) => 'mapOf(${_element(value)})',
};

String _element(TypeRef t) =>
    t.nullable && !_isAny(t) ? 'nullable(${decoder(t)})' : decoder(t);

/// The JSON value of a request [expr] of type [t]: an enum is sent as its wire value.
String encode(TypeRef t, String expr) {
  final q = t.nullable ? '?' : '';
  return switch (t) {
    EnumType() => '$expr$q.wire',
    ListType(item: EnumType(nullable: false)) =>
      '$expr$q.map((e) => e.wire).toList()',
    ListType(item: final item) when _hasEnum(item) => fail(
      '$expr: a nested enum list',
    ),
    MapType(value: final value) when _hasEnum(value) => fail(
      '$expr: an enum map',
    ),
    _ => expr,
  };
}

bool _hasEnum(TypeRef t) => switch (t) {
  EnumType() => true,
  ListType(:final item) => _hasEnum(item),
  MapType(:final value) => _hasEnum(value),
  _ => false,
};

String _entry(String wire, TypeRef t, String expr, {required bool required}) {
  final value = encode(required ? t : t.withNullable(true), expr);
  return required
      ? '${dartString(wire)}: $value'
      : '${dartString(wire)}: ?$value';
}

String _parameter(String name, TypeRef t, {required bool required}) => required
    ? 'required ${typeCode(t)} $name'
    : '${typeCode(t.withNullable(true))} $name';

String enumsLibrary(Api api) {
  final out = StringBuffer(header);
  for (final e in api.enums) {
    out
      ..write('\n/// Values the API accepts for `${e.key}`.\n')
      ..write('enum ${e.name} {\n');
    for (final v in e.values) {
      out.write('  /// `$v`\n  ${enumMember(v)}(${dartString(v)}),\n');
    }
    out.write(
      '  ;\n\n  const ${e.name}(this.wire);\n\n  /// The value sent to the API.\n  final String wire;\n}\n',
    );
  }
  return out.toString();
}

String modelsLibrary(Api api) {
  final out = StringBuffer(
    '$header\nimport \'enums.g.dart\';\nimport \'json.dart\';\n',
  );
  final names = api.models.keys.toList()..sort();
  for (final name in names) {
    final m = api.models[name] ?? fail('unreachable');
    out
      ..write('\n')
      ..write(doc(m.description))
      ..write(
        'extension type $name.fromJson(Map<String, Object?> json) implements Object {\n',
      );
    if (m.sides.contains(Side.request)) {
      final fields = m.fields;
      final params = [
        for (final f in fields)
          _parameter(f.dart, _requestType(f), required: f.required),
      ];
      final entries = [
        for (final f in fields)
          _entry(f.wire, _requestType(f), f.dart, required: f.required),
      ];
      out.write('  /// Builds the object to send.\n');
      out.write(
        params.isEmpty
            ? '  $name() : json = <String, Object?>{};\n'
            : '  $name({${params.join(', ')},}) : json = <String, Object?>{${entries.join(', ')},};\n',
      );
    }
    if (m.sides.contains(Side.response)) {
      for (final f in m.fields) {
        final t = f.types[Side.response] ?? fail('unreachable');
        out
          ..write('\n')
          ..write(doc(f.description ?? '`${f.wire}`', '  '));
        if (_isAny(t)) {
          out.write(
            '  Object? get ${f.dart} => json[${dartString(f.wire)}];\n',
          );
        } else if (f.required && !t.nullable) {
          out.write(
            '  ${typeCode(t)} get ${f.dart} => read(json, ${dartString(f.wire)}, ${decoder(t)});\n',
          );
        } else {
          out.write(
            '  ${typeCode(t.withNullable(true))} get ${f.dart} => readOrNull(json, ${dartString(f.wire)}, ${decoder(t)});\n',
          );
        }
      }
    }
    out.write('}\n');
  }
  return out.toString();
}

TypeRef _requestType(Field f) => f.types[Side.request] ?? fail('unreachable');

String namespaceClass(Domain d) => '${pascal(d.namespace)}Api';

String apiLibrary(Api api) {
  final out = StringBuffer(header)
    ..write(
      "\nimport 'enums.g.dart';\nimport 'json.dart';\nimport 'models.g.dart';\n",
    )
    ..write("import 'transport.dart';\n\n")
    ..write(
      '/// The base URL of every request.\nconst apiBaseUrl = ${dartString(api.baseUrl)};\n\n',
    );
  final taken = {...api.models.keys, for (final e in api.enums) e.name};
  for (final d in api.domains) {
    if (!taken.add(namespaceClass(d))) {
      fail('the class name ${namespaceClass(d)} is taken');
    }
  }
  out.write(
    '/// One namespace per domain of the API.\nabstract base class RoxyNamespaces {\n',
  );
  out.write('  /// Creates every namespace over [transport].\n');
  out.write(
    '  RoxyNamespaces(Transport transport) : ${api.domains.map((d) => '${d.namespace} = ${namespaceClass(d)}(transport)').join(', ')};\n',
  );
  for (final d in api.domains) {
    out
      ..write('\n')
      ..write('  /// The ${d.tag} endpoints.\n')
      ..write('  final ${namespaceClass(d)} ${d.namespace};\n');
  }
  out.write('}\n');
  for (final d in api.domains) {
    out
      ..write('\n')
      ..write(
        doc(
          '${d.tag}. ${d.description ?? ''}\n\nAPI reference: ${d.referenceUrl}',
        ),
      )
      ..write('final class ${namespaceClass(d)} {\n')
      ..write('  /// Creates the namespace over [_transport].\n')
      ..write('  const ${namespaceClass(d)}(this._transport);\n\n')
      ..write('  final Transport _transport;\n');
    for (final op in d.operations) {
      out
        ..write('\n')
        ..write(_methodDoc(op))
        ..write(_method(op));
    }
    out.write('}\n');
  }
  return out.toString();
}

String _methodDoc(Operation op) {
  final parts = <String>[
    if (op.summary != null) op.summary ?? '',
    if (op.description != null && op.description != op.summary)
      op.description ?? '',
    if (op.params.isNotEmpty)
      [
        for (final p in op.params)
          '- `${p.dart}`: ${(p.description ?? p.wire).replaceAll('\n', ' ')}',
      ].join('\n'),
    '`${op.verb.toUpperCase()} ${op.path}`',
  ];
  return doc(parts.join('\n\n'), '  ');
}

String _method(Operation op) {
  final params = [
    for (final p in op.params) _parameter(p.dart, p.type, required: p.required),
  ];
  final path = _pathLiteral(op);
  String entries(ParamSource source) => [
    for (final p in op.params.where((p) => p.source == source))
      _entry(p.wire, p.type, p.dart, required: p.required),
  ].map((e) => '$e,').join();
  final query = op.params.any((p) => p.source == ParamSource.query)
      ? ', query: <String, Object?>{${entries(ParamSource.query)}}'
      : '';
  final body = op.hasBody
      ? ', body: <String, Object?>{${entries(ParamSource.body)}}'
      : '';
  final signature = params.isEmpty ? '' : '{${params.join(', ')},}';
  return '  Future<${typeCode(op.response)}> ${op.operationId}($signature) async =>\n'
      '      ${decoder(op.response)}(await _transport.send(${dartString(op.verb.toUpperCase())}, $path$query$body), \'response\');\n';
}

/// The path of [op] as a Dart string literal, each `{param}` interpolated and encoded.
String _pathLiteral(Operation op) {
  if (!RegExp(r'^[A-Za-z0-9/_{}-]+$').hasMatch(op.path)) {
    fail('${op.operationId}: unsupported path characters in ${op.path}');
  }
  final body = op.path.replaceAllMapped(RegExp(r'\{([^}]+)\}'), (m) {
    final p = op.params.firstWhere(
      (p) => p.source == ParamSource.path && p.wire == m[1],
      orElse: () => fail('${op.operationId}: no parameter for {${m[1]}}'),
    );
    return switch (p.type) {
      EnumType() => '\${Uri.encodeComponent(${p.dart}.wire)}',
      ScalarType(scalar: Scalar.string) => '\${Uri.encodeComponent(${p.dart})}',
      ScalarType(scalar: Scalar.integer) => '\$${p.dart}',
      _ => fail('${op.operationId}: unsupported path parameter type'),
    };
  });
  return "'$body'";
}

String errorCodesLibrary(Api api) {
  final out = StringBuffer(header)
    ..write(
      '\n/// Every error `code` the API documents. A code added later arrives as a plain\n',
    )
    ..write(
      '/// string, so compare `RoxyException.code` against these and keep a default branch.\n',
    )
    ..write('abstract final class ErrorCodes {\n');
  final names = <String>{};
  for (final c in api.errorCodes) {
    final name = memberName(c.code, taken: const {'all'});
    if (!names.add(name)) fail('error codes collide on $name');
    out
      ..write(doc('${c.status ?? 'Any'}: ${c.meaning}', '  '))
      ..write('  static const $name = ${dartString(c.code)};\n\n');
  }
  out
    ..write('  /// Every code above, in the order the API documents them.\n')
    ..write('  static const all = [${names.join(', ')}];\n}\n');
  return out.toString();
}

/// Spec-example values rendered as Dart expressions, for the method reference and
/// `test/calls.g.dart`.
final class Examples {
  Examples(this.api);
  final Api api;

  /// One call of [op] with the values the spec gives as examples.
  String call(Operation op) {
    final args = <String>[];
    for (final p in op.params) {
      if (p.wire == 'lang' && p.source == ParamSource.query) continue;
      if (!p.required && p.example == null) continue;
      args.add(
        '${p.dart}: ${literal(p.type, p.example ?? p.schema['default'])}',
      );
    }
    return 'roxy.${op.namespace}.${op.operationId}(${args.join(', ')})';
  }

  /// A Dart expression of type [t] for the spec example [value], or a typed placeholder.
  String literal(TypeRef t, Object? value) {
    switch (t) {
      case ScalarType(scalar: Scalar.string):
        return dartString(value is String ? value : 'string');
      case ScalarType(scalar: Scalar.integer):
        return value is num ? '${value.toInt()}' : '0';
      case ScalarType(scalar: Scalar.number):
        return value is num ? '$value' : '0';
      case ScalarType(scalar: Scalar.boolean):
        return value is bool ? '$value' : 'false';
      case ScalarType(scalar: Scalar.any || Scalar.object):
        return value is Map
            ? '<String, Object?>${jsonLiteral(value)}'
            : '<String, Object?>{}';
      case NumOrStringType():
        return value is num
            ? 'NumOrString.number($value)'
            : 'NumOrString.string(${dartString(value is String ? value : 'UTC')})';
      case EnumType(:final occurrence):
        final values = occurrence.values;
        final chosen = value is String && values.contains(value)
            ? value
            : values.first;
        return '${occurrence.name}.${enumMember(chosen)}';
      case ListType(:final item):
        final items = value is List ? value : const <Object?>[];
        return '[${items.map((v) => literal(item, v)).join(', ')}]';
      case MapType(value: final v):
        final entries = value is Map
            ? value.entries
            : const <MapEntry<Object?, Object?>>[];
        return '<String, ${typeCode(v)}>{${entries.map((e) => '${dartString('${e.key}')}: ${literal(v, e.value)}').join(', ')}}';
      case ModelType(:final name):
        return _model(name, value);
    }
  }

  /// A constructor call of the request model [name], filled from [value] or field examples.
  String _model(String name, Object? value) {
    final model = api.models[name] ?? fail('unknown model $name');
    final source = value is Map ? value : const <Object?, Object?>{};
    final args = <String>[];
    for (final f in model.fields) {
      final example = source[f.wire] ?? f.schema['example'];
      if (!f.required && example == null) continue;
      args.add(
        '${f.dart}: ${literal(f.types[Side.request] ?? fail('unreachable'), example)}',
      );
    }
    return '$name(${args.join(', ')})';
  }
}

String jsonLiteral(Object? value) => switch (value) {
  null => 'null',
  final String s => dartString(s),
  final num n => '$n',
  final bool b => '$b',
  final List<Object?> l => '[${l.map(jsonLiteral).join(', ')}]',
  final Map<Object?, Object?> m =>
    '{${m.entries.map((e) => '${dartString('${e.key}')}: ${jsonLiteral(e.value)}').join(', ')}}',
  _ => fail('unsupported example value ${jsonEncode(value)}'),
};

String callsLibrary(Api api) {
  final out = StringBuffer(header)
    ..write("\nimport 'package:roxyapi/roxyapi.dart';\n\n")
    ..write(
      '/// Every method, called once with the values the spec gives as examples, exactly as the\n',
    )
    ..write(
      '/// method reference prints them. Compiled by the analyzer, never run.\n',
    )
    ..write('Future<void> calls(Roxy roxy) async {\n');
  final examples = Examples(api);
  for (final op in api.operations) {
    out.write('  await ${examples.call(op)};\n');
  }
  out.write('}\n');
  return out.toString();
}
